def json_kind(value):
    if value is MISSING: return 'missing'
    if value is None: return 'null'
    if type(value) is bool: return 'boolean'
    if isinstance(value, (int, float)): return 'number'
    if isinstance(value, str): return 'string'
    if isinstance(value, list): return 'array'
    if isinstance(value, dict): return 'object'
    return 'unsupported'

def deep_equal(left, right):
    if json_kind(left) != json_kind(right): return False
    if isinstance(left, dict):
        return set(left) == set(right) and all(deep_equal(left[k], right[k]) for k in left)
    if isinstance(left, list):
        return len(left) == len(right) and all(deep_equal(a, b) for a, b in zip(left, right))
    return left == right

def path_get(value, path):
    for key in path:
        if not isinstance(value, dict) or key not in value: return MISSING
        value = value[key]
    return value

def declared_values(spec):
    if isinstance(spec, dict) and 'values_ref' in spec:
        return path_get(OPERATOR_RULES, spec['values_ref'])
    return spec

def conditional_value_violation(record, field, policy):
    if not isinstance(record, dict): return False
    if record.get(field, MISSING) not in declared_values(policy['values']): return False
    evidence = path_get(record, policy['evidence_path'])
    if not isinstance(evidence, list): return policy['non_array_is_insufficient']
    return len(evidence) in policy['insufficient_item_counts']

def is_declared_placeholder(value, rule, field):
    if value is MISSING or value is None: return False
    markers=declared_values(rule.get('values_by_field', {}).get(field, []))
    if isinstance(value,str) and value in markers: return True
    if isinstance(value,dict):
        return any(is_declared_placeholder(v,rule,field) for v in value.values())
    if isinstance(value,list):
        return any(is_declared_placeholder(v,rule,field) for v in value)
    return False

def field_placeholder_pair(a,b,rule,field):
    if is_declared_placeholder(a,rule,field) or is_declared_placeholder(b,rule,field):return True
    return field in rule.get('empty_array_fields',[]) and deep_equal(a,b) and isinstance(a,list) and not a


def project(value, fields):
    if value is MISSING: return MISSING
    if value is None: return None
    if not isinstance(value, dict): return MISSING
    return {key: value[key] for key in fields if key in value}

def aggregate_comparisons(values, rule):
    if all(value == rule['all_fields_corresponding'] for value in values):
        return rule['all_fields_corresponding']
    for status in rule['otherwise_precedence']:
        if status in values: return status
    raise ValueError('formal aggregation rule has no result for ' + repr(values))

def compare_fields(left, right, fields, placeholder_rule=None):
    rule = OPERATOR_RULES['compare_fields']['field_presence_rules']
    roots=OPERATOR_RULES['compare_fields']['operand_root_rules']
    if left is MISSING or right is MISSING: return roots['either_operand_absent']
    if left is None or right is None: return roots['either_operand_null']
    if not isinstance(left, dict) or not isinstance(right, dict): return roots['either_operand_non_object']
    result = {}
    placeholders = placeholder_rule or OPERATOR_RULES['compare_fields'].get('placeholder_rule', {})
    for field in fields:
        a, b = left.get(field, MISSING), right.get(field, MISSING)
        if a is MISSING and b is MISSING: status = rule['both_absent']
        elif a is MISSING or b is MISSING: status = rule['exactly_one_absent']
        elif field_placeholder_pair(a,b,placeholders,field): status = placeholders.get('result', 'unknown')
        elif field in placeholders.get('expected_values_by_field',{}) and (not deep_equal(a,placeholders['expected_values_by_field'][field]) or not deep_equal(b,placeholders['expected_values_by_field'][field])):status='content_conflict'
        elif a in declared_values(placeholders.get('forbidden_values_by_field',{}).get(field,[])) or b in declared_values(placeholders.get('forbidden_values_by_field',{}).get(field,[])):status='content_conflict'
        elif field in placeholders.get('conditional_forbidden_values_by_field',{}) and (conditional_value_violation(left,field,placeholders['conditional_forbidden_values_by_field'][field]) or conditional_value_violation(right,field,placeholders['conditional_forbidden_values_by_field'][field])):status='content_conflict'
        else: status = 'content_corresponding_in_fixture' if deep_equal(a, b) else 'content_conflict'
        result[field] = status
    return result

def compare_single(left, right, fields, placeholder_rule=None):
    spec = OPERATOR_RULES['compare_record']
    roots = spec['root_presence_rules']
    if left is MISSING or right is MISSING: return roots['either_record_absent']
    if left is None or right is None: return roots['either_record_null']
    statuses = compare_fields(left, right, fields, placeholder_rule)
    if isinstance(statuses, str): return statuses
    return aggregate_comparisons(list(statuses.values()), spec['aggregate_rule'])

def compare_contract_entry(left, right, fields, expression):
    spec = OPERATOR_RULES['contract_selection']
    roots = spec['selected_reference_presence_rules']
    missing_order=expression['missing_precedence'];null_order=expression['null_precedence']
    if left is MISSING or right is MISSING:
        if 'selected_entry_absent' in missing_order:return roots['selected_entry_absent']
        raise ValueError('formal contract-selection rule omits absent selected entry')
    if left is None or right is None:
        if 'selected_entry_null' in null_order:return roots['selected_entry_null']
        raise ValueError('formal contract-selection rule omits null selected entry')
    if not isinstance(left, dict) or not isinstance(right, dict): return 'content_conflict'
    statuses=[]; rules=spec['required_field_rules']
    for field in fields:
        a,b=left.get(field,MISSING),right.get(field,MISSING)
        if a is MISSING or b is MISSING: statuses.append(rules['field_absent'])
        elif a is None or b is None: statuses.append(rules['field_null'])
        elif deep_equal(a,b): statuses.append(rules['present_equal'])
        else: statuses.append(rules['present_unequal'])
    for decision in expression['decision_order']:
        if decision=='missing_if_any_required_field_absent' and 'field_absent' in missing_order and rules['field_absent'] in statuses:return rules['field_absent']
        if decision=='unknown_if_map_entry_or_required_field_is_null' and 'field_null' in null_order and rules['field_null'] in statuses:return rules['field_null']
        if decision=='content_conflict_if_any_present_value_differs' and rules['present_unequal'] in statuses:return rules['present_unequal']
        if decision=='content_corresponding_in_fixture_if_all_present_values_equal' and all(x==rules['present_equal'] for x in statuses):return rules['present_equal']
    raise ValueError('contract selection rule has no result for ' + repr(statuses))

def prerequisite_violation(check,root):
    for state_root in check['roots']:
        states=path_get(root,[state_root])
        if not isinstance(states,dict):continue
        adoption=states.get(check['trigger']['key'],{})
        if not isinstance(adoption,dict) or adoption.get(check['trigger']['field'],MISSING) not in declared_values(check['trigger']['one_of']):continue
        for prerequisite in check['prerequisites']:
            item=states.get(prerequisite['key'],{})
            if not isinstance(item,dict) or item.get(prerequisite['field'],MISSING) not in declared_values(prerequisite['one_of']):return True
    return False


def eval_expr(expression, root, result):
    if not isinstance(expression, dict): return expression
    op = expression.get('op')
    if not op:
        if 'path' in expression: return path_get(root, expression['path'])
        return {k: eval_expr(v, root, result) for k, v in expression.items()}
    if op in ('get', 'read_nested'): return path_get(root, expression['path'])
    if op == 'constant': return expression['value']
    if op in ('project', 'project_nullable'):
        return project(eval_expr(expression['value'], root, result), expression['fields'])
    if op == 'compare_fields':
        return compare_fields(eval_expr(expression['left'], root, result), eval_expr(expression['right'], root, result), expression['fields'], expression.get('placeholder_rule'))
    if op == 'build_receipt_candidate':
        candidate = path_get(root, expression['candidate']); evaluation = path_get(root, expression['evaluation'])
        mapping = {'source': (candidate, 'source'), 'candidate_identity': (candidate, 'identity'),
                   'candidate_revision': (candidate, 'revision'), 'candidate_version': (candidate, 'version'),
                   'evaluation_identity': (evaluation, 'identity'), 'evaluation_revision': (evaluation, 'revision'),
                   'scope': (evaluation, 'scope')}
        out = {}
        for field in expression['fields']:
            obj, key = mapping[field]
            if isinstance(obj, dict) and key in obj: out[field] = obj[key]
        return out
    if op == 'candidate_maturity_state':
        selected = path_get(root, expression['selection']); maturity = result.get('maturity_result', MISSING)
        original = path_get(root, expression['original'])
        if selected is False: return 'not_required'
        if selected is MISSING or selected is None or maturity != 'content_corresponding_in_fixture': return 'held_unknown_or_conflicting'
        if original is MISSING or original is None or not isinstance(original, dict): return 'held_unknown_or_conflicting'
        if any(k not in original or original[k] is None for k in expression['required_original_fields']): return 'held_unknown_or_conflicting'
        return 'original_state_in_fixture_only'
    if op == 'compare_target':
        left = eval_expr(expression['left'], root, result); right = eval_expr(expression['right'], root, result)
        if left is MISSING or left is None: return 'missing'
        if right is MISSING or right is None or not isinstance(left, dict) or not isinstance(right, dict): return 'candidate_target_information_unknown'
        fields = expression['fields']
        placeholder_fields=expression.get('placeholder_values_by_field',{})
        if any(left.get(k, MISSING) in (MISSING, None) or right.get(k, MISSING) in (MISSING, None) or left.get(k,MISSING) in declared_values(placeholder_fields.get(k,[])) or right.get(k,MISSING) in declared_values(placeholder_fields.get(k,[])) for k in fields): return 'candidate_target_information_unknown'
        return 'same_exact_candidate_in_fixture' if all(deep_equal(left[k], right[k]) for k in fields) else 'different_candidate'
    if op in ('collect_null_keys', 'collect_missing_keys'):
        obj = eval_expr(expression['value'], root, result); fields = expression['fields']
        if not isinstance(obj, dict): return []
        if op == 'collect_null_keys': return [k for k in fields if k in obj and obj[k] is None]
        return [k for k in fields if k not in obj]
    if op == 'claim_results':
        obj = eval_expr(expression['value'], root, result)
        out={k: ('unknown' if not isinstance(obj, dict) or k not in obj or type(obj[k]) is not bool else 'none' if obj[k] is False else 'rejected') for k in expression['fields']}
        for check in expression.get('additional_checks', []):
            if 'policy_ref' in check:check=path_get(PROGRAMS,check['policy_ref'])
            if 'selection_path' in check and path_get(root,check['selection_path']) is not True:continue
            if check['kind']=='placeholder_pair':
                left=path_get(root,check['left']); right=path_get(root,check['right'])
                if 'fields' not in check:
                    values=(left,right); names=[check.get('field',check['name'])]
                else:
                    names=check['fields']; values=[]
                    for field in names:
                        values.append((left.get(field,MISSING) if isinstance(left,dict) else MISSING,right.get(field,MISSING) if isinstance(right,dict) else MISSING))
                if 'fields' not in check:
                    values=[values]
                for field,pair_values in zip(names,values):
                    rule={'values_by_field':{field:check.get('markers',[])},'empty_array_fields':check.get('empty_arrays',[]) if isinstance(check.get('empty_arrays',[]),list) else []}
                    marked=[field_placeholder_pair(pair_values[0],pair_values[1],rule,field)]
                    if any(marked): out[check['name'] if 'fields' not in check else check['name']+'_'+field]='unknown'
            elif check['kind']=='forbidden_value':
                value=path_get(root,check['path'])
                if value in declared_values(check['values']) and ('equal_pair_path' not in check or deep_equal(value,path_get(root,check['equal_pair_path']))):
                    if 'condition_policy_ref' in check:
                        policy=path_get(PROGRAMS,check['condition_policy_ref'])
                        if not any(conditional_value_violation(path_get(root,path),check['condition_field'],policy) for path in check['condition_record_paths']):continue
                    out[check['name']]='rejected'
            elif check['kind']=='owner_role':
                value=path_get(root,check['path'])
                if 'require_object_path' in check and not isinstance(path_get(root,check['require_object_path']),dict):continue
                if 'equal_pair_path' in check and not deep_equal(value,path_get(root,check['equal_pair_path'])):continue
                if value is MISSING or value is None or value in declared_values(check.get('markers',[])): out[check['name']]='unknown'
                elif value!=check['expected']:out[check['name']]='rejected'
            elif check['kind']=='state_prerequisite':
                if prerequisite_violation(check,root) and (path_get(root,check['same_state_paths'][0])==check['trigger']['always_diagnose_value'] or path_get(root,check['same_state_paths'][1])==check['trigger']['always_diagnose_value'] or deep_equal(path_get(root,check['same_state_paths'][0]),path_get(root,check['same_state_paths'][1]))):out[check['name']]='rejected'
            elif check['kind']=='selection_state':
                selected=path_get(root,check['selection']);state=path_get(root,check['state'])
                expected=check['when_true'] if selected is True else check['when_false'] if selected is False else MISSING
                if expected is MISSING or state is MISSING or state is None or state in declared_values(check['markers']):out[check['name']]='unknown'
                elif not deep_equal(state,expected):out[check['name']]='rejected' if state in declared_values(check['known_state_values']) else 'unknown'
            else: raise ValueError('unknown additional claim check '+check['kind'])
        return out
    if op == 'false_effects': return {k: False for k in expression['fields']}
    if op == 'is_false': return path_get(root, expression['path']) is False
    if op == 'is_true': return path_get(root, expression['path']) is True
    if op == 'is_absent_or_null':
        value = path_get(root, expression['path']); return value is MISSING or value is None
    if op == 'otherwise': return True
    if op == 'conditional':
        for arm in expression['arms']:
            if eval_expr(arm['when'], root, result):
                return eval_expr(arm['value'], root, result) if 'value' in arm else arm.get('then', MISSING)
        return MISSING
    if op == 'candidate_state':
        spec=OPERATOR_RULES['candidate_state']['decision_rule']
        fs=expression['candidate_fields']; evfs=expression['evaluation_fields']
        objs=[eval_expr(expression[k],root,result) for k in ['candidate_original','candidate_submitted','evaluation_original','evaluation_submitted']]
        for obj,fields in zip(objs,[fs,fs,evfs,evfs]):
            if obj is MISSING or obj is None or not isinstance(obj,dict) or any(k not in obj or obj[k] is None for k in fields):return spec['if_any_check_fails']
        cand=eval_expr(expression['candidate_comparison_results'],root,result)
        ev=eval_expr(expression['evaluation_comparison_results'],root,result)
        target=eval_expr(expression['target_result'],root,result)
        corresponding=OPERATOR_RULES['candidate_state']['comparison_status_inputs']['candidate_comparison_results']['required_status']
        if not isinstance(cand,dict) or not isinstance(ev,dict):return spec['if_any_check_fails']
        if any(k not in cand or cand[k]!=corresponding for k in fs):return spec['if_any_check_fails']
        if any(k not in ev or ev[k]!=corresponding for k in evfs):return spec['if_any_check_fails']
        target_status=OPERATOR_RULES['candidate_state']['comparison_status_inputs']['target_result']['required_status']
        return spec['if_all_checks_pass'] if target==target_status else spec['if_any_check_fails']
    if op in ('compare_record', 'compare_receipt'):
        left = eval_expr(expression['left'], root, result); right = eval_expr(expression['right'], root, result)
        if op == 'compare_receipt':
            roots = OPERATOR_RULES['compare_receipt']['root_presence_rules']
            if left is MISSING or right is MISSING: return roots['either_receipt_absent']
            if left is None or right is None: return roots['either_receipt_null']
            spec=OPERATOR_RULES['compare_receipt']
            markers=declared_values(expression.get('placeholder_values',[]))
            if any((isinstance(left,dict) and left.get(k,MISSING) in markers) or (isinstance(right,dict) and right.get(k,MISSING) in markers) for k in expression['fields']):return expression.get('placeholder_result','unknown')
        return compare_single(left, right, expression['fields'],expression.get('placeholder_rule'))
    if op == 'compare_nested_maps':
        left = eval_expr(expression['left'], root, result); right = eval_expr(expression['right'], root, result)
        out={key: compare_single(left.get(key, MISSING) if isinstance(left, dict) else MISSING,
                                    right.get(key, MISSING) if isinstance(right, dict) else MISSING,
                                    expression['fields'],expression.get('rules_by_key',{}).get(key,{})) for key in expression['keys']}
        if prerequisite_violation(expression['prerequisite_policy'],root):out[expression['prerequisite_policy']['trigger']['key']]='content_conflict'
        return out
    if op == 'project_nested_maps':
        value = eval_expr(expression['value'], root, result)
        return {key: project(value[key], expression['fields']) for key in expression['keys'] if isinstance(value, dict) and key in value}
    if op == 'fixed_owner_roles': return expression['value']
    if op == 'maturity_result':
        selected=path_get(root,expression['selection']); original=path_get(root,expression['original']); submitted=path_get(root,expression['submitted']); candidate=path_get(root,expression['candidate'])
        fields=expression['compared_fields']; binding=expression['binding_fields']
        if selected is False:return 'not_selected_not_required'
        if selected is MISSING or selected is None:return 'unknown_selection'
        if original is MISSING or original is None or any(k not in original or original[k] is None for k in fields):return 'unknown_original_maturity_information'
        if submitted is MISSING or submitted is None:return 'missing'
        marker_fields=expression.get('placeholder_values_by_field',{})
        if any(field_placeholder_pair(original.get(k,MISSING),submitted.get(k,MISSING),{'values_by_field':marker_fields,'empty_array_fields':expression.get('empty_array_fields',[])},k) for k in fields):return expression.get('placeholder_result','unknown_original_maturity_information')
        if compare_single(original,submitted,fields,expression.get('placeholder_rule'))!='content_corresponding_in_fixture':return 'content_conflict'
        mapping=expression['binding_mapping']
        if not isinstance(candidate,dict) or any(original.get(maturity_field,MISSING) in (MISSING,None) or candidate.get(candidate_field,MISSING) in (MISSING,None) for maturity_field,candidate_field in mapping):return 'different_candidate_target'
        return 'content_corresponding_in_fixture' if all(deep_equal(original[mf],candidate[cf]) for mf,cf in mapping) else 'different_candidate_target'
    if op == 'maturity_submission_result':
        selected=path_get(root,expression['selection']);original=path_get(root,expression['original']);submitted=path_get(root,expression['submitted'])
        if selected is False:return 'not_selected_not_required'
        if selected is MISSING or selected is None:return 'selection_unknown'
        if submitted is MISSING or submitted is None:return 'missing'
        if original is MISSING or original is None:return 'original_unknown'
        marker_fields=expression.get('placeholder_values_by_field',{})
        if any(field_placeholder_pair(original.get(k,MISSING),submitted.get(k,MISSING),{'values_by_field':marker_fields,'empty_array_fields':expression.get('empty_array_fields',[])},k) for k in expression['compared_fields']):return expression.get('placeholder_result','original_unknown')
        return compare_single(original,submitted,expression['compared_fields'],expression.get('placeholder_rule'))
    if op == 'contract_selection':
        original=eval_expr(expression['original'],root,result); submitted=eval_expr(expression['submitted'],root,result)
        selected=list(expression['always'])
        for group,flag in [('when_composition_selected','composition_selected_path'),('when_failure_knowledge_selected','failure_selected_path')]:
            if path_get(root,expression[flag]) is True:selected.extend(expression[group])
        out={}; rules=OPERATOR_RULES['contract_selection']['selected_reference_presence_rules']
        for key in selected:
            if original is MISSING or submitted is MISSING:
                if 'map_absent' not in expression['missing_precedence']:raise ValueError('AST omits absent reference map rule')
                out[key]=rules['map_absent']; continue
            if original is None or submitted is None:
                if 'map_null' not in expression['null_precedence']:raise ValueError('AST omits null reference map rule')
                out[key]=rules['map_null']; continue
            left=original.get(key,MISSING) if isinstance(original,dict) else MISSING
            right=submitted.get(key,MISSING) if isinstance(submitted,dict) else MISSING
            status=compare_contract_entry(left,right,expression['fields'],expression)
            placeholder_values=expression.get('placeholder_values_by_field',{})
            if status not in ['missing','unknown'] and isinstance(left,dict) and isinstance(right,dict) and any(left.get(field,MISSING) in declared_values(placeholder_values.get(field,[])) or right.get(field,MISSING) in declared_values(placeholder_values.get(field,[])) for field in expression['fields']):
                status=expression.get('placeholder_result','unknown')
            expected=expression['expected_identity_by_key'].get(key,MISSING)
            if expected is MISSING:raise ValueError('AST expected identity missing for selected slot '+key)
            if status=='content_corresponding_in_fixture':
                # The AST's source-bound slot identity is an additional comparison
                # operand. Missing/null already returned through the established
                # precedence above and is not reclassified here.
                left_identity=left.get('identity',MISSING) if isinstance(left,dict) else MISSING
                right_identity=right.get('identity',MISSING) if isinstance(right,dict) else MISSING
                if not deep_equal(left_identity,expected) or not deep_equal(right_identity,expected):
                    status='content_conflict'
            out[key]=status
        return out
    if op == 'contract_unselected':
        out=[]
        for item in expression['selectors']:
            selected=path_get(root,item['path'])
            if selected is False:out.append(item['key'])
        return out
    if op == 'route_state_differences':
        left=eval_expr(expression['left'],root,result);right=eval_expr(expression['right'],root,result);out={}
        for key in expression['keys']:
            a=left.get(key,MISSING) if isinstance(left,dict) else MISSING;b=right.get(key,MISSING) if isinstance(right,dict) else MISSING
            route_equal=expression.get('route_on_equal_values',{}).get(key,[])
            av=a.get('state',MISSING) if isinstance(a,dict) else MISSING;bv=b.get('state',MISSING) if isinstance(b,dict) else MISSING
            if (result[expression['status_ref']][key]!='content_corresponding_in_fixture' or av in route_equal or bv in route_equal) and key in expression['owner_by_key']:out[key]=expression['owner_by_key'][key]
        return out
    if op == 'same_as': return result.get(expression['ref'], MISSING)
    raise ValueError('unknown operator: '+op)

def run_program(requirement_ref, raw):
    result={}
    for key, expression in PROGRAMS[requirement_ref]["output"].items():
        result[key]=eval_expr(expression,raw,result)
    return result
